import overcrow from './overcrow.js';
const status = document.querySelector('#status');
try {
  status.textContent = 'Chargement…';
  const response = await overcrow.fetch('https://api.warframe.market/v2/items');
  if (!response.ok) throw new Error('HTTP ' + response.status);
  const payload = await response.json();
  if (!Array.isArray(payload.data)) throw new Error('Catalogue invalide');
  status.textContent = payload.data.length + ' objets disponibles';
} catch (error) {
  status.textContent = 'Catalogue indisponible. Réessayez.';
  console.error(error.code ?? error.message); // Local development diagnostic.
}

import overcrow from './overcrow.js';
const snapshot = await overcrow.game.snapshot();
const ms = snapshot.sessionElapsedMs;
const minutes = typeof ms === 'number' ? Math.floor(ms / 60000) : null;
document.querySelector('#duration').textContent =
  minutes === null ? 'Session indisponible' : minutes + ' min';

import overcrow from './overcrow.js';
function render(snapshot) {
  const ms = snapshot.sessionElapsedMs;
  document.querySelector('#duration').textContent =
    typeof ms === 'number' ? Math.floor(ms / 60000) + ' min' : 'Session indisponible';
}
const stop = overcrow.game.onSnapshot(render);
render(await overcrow.game.snapshot());
// Call stop() when the component is destroyed.

