import overcrow from './overcrow.js';
const state = { count: 0 };
overcrow.runtime.onMessage(async message => {
  if (!message || typeof message !== 'object') return;
  if (message.type === 'increment') state.count += 1;
  if (message.type === 'hello' || message.type === 'increment') {
    await overcrow.runtime.send({ type: 'state', count: state.count });
  }
});

import overcrow from './overcrow.js';
overcrow.runtime.onMessage(message => {
  if (message?.type !== 'state' || !Number.isSafeInteger(message.count)) return;
  document.querySelector('#count').textContent = String(message.count);
});
await overcrow.runtime.send({ type: 'hello' });
document.querySelector('#increment').addEventListener('click', () => {
  overcrow.runtime.send({ type: 'increment' }).catch(console.error);
});

const stop = overcrow.lifecycle.onVisibility(visible => {
  document.body.dataset.visible = String(visible);
  // Pause animations or work that is no longer needed.
});

function readPreferences() {
  try {
    const value = JSON.parse(localStorage.getItem('preferences.v1') ?? '{}');
    return { compact: value?.compact === true };
  } catch {
    return { compact: false };
  }
}
function savePreferences(preferences) {
  try {
    localStorage.setItem('preferences.v1', JSON.stringify(preferences));
    return true;
  } catch {
    return false; // Show that the setting remains in memory only.
  }
}

"localization": {
  "defaultLocale": "en",
  "availableLocales": ["en", "fr"]
}

import overcrow from './overcrow.js';
const messages = {
  en: { ready: 'Ready' },
  fr: { ready: 'Prêt' }
};
function render(locale) {
  const selected = messages[locale] ?? messages.en;
  document.querySelector('#status').textContent = selected.ready;
}
const stop = overcrow.locale.onChanged(render);
render(await overcrow.locale.getCurrent());

import overcrow from './overcrow.js';
document.querySelector('#copy').addEventListener('click', async () => {
  const status = document.querySelector('#status');
  try {
    await overcrow.clipboard.writeText('Bonjour depuis OverCrow');
    status.textContent = 'Copié';
  } catch (error) {
    status.textContent = 'Copie refusée. Cliquez de nouveau en mode interactif.';
  }
});

